            case "NORDESTE" -> new BigDecimal("0.02");
            default -> throw new CheckoutException("REGIAO_INVALIDA");
        };
        return round(subtotal.multiply(taxa));
    }

    private void validarParcelas(String formaPagamento, int parcelas) {
