    @Test
    void freteGratis_descontoCupomIgualAoFrete() throws Exception {
        String json = """
                {
                  "itens": [
                    {"nome":"Camiseta","precoUnitario":79.90,"quantidade":2,"pesoKg":0.30}
                  ],
                  "modalidadeEntrega":"EXPRESSA",
                  "formaPagamento":"PIX",
                  "nivelClube":"BRONZE",
                  "regiao":"SUDESTE"
                }
                """;

        mockMvc.perform(post(URL).contentType(MediaType.APPLICATION_JSON).content(json))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.frete").value(27.70));

        String jsonComFreteGratis = """
                {
                  "itens": [
                    {"nome":"Camiseta","precoUnitario":79.90,"quantidade":2,"pesoKg":0.30}
                  ],
                  "modalidadeEntrega":"EXPRESSA",
                  "cupom":"FRETEGRATIS",
                  "formaPagamento":"PIX",
                  "nivelClube":"BRONZE",
                  "regiao":"SUDESTE"
                }
                """;

        mockMvc.perform(post(URL).contentType(MediaType.APPLICATION_JSON).content(jsonComFreteGratis))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.frete").value(27.70))
                .andExpect(jsonPath("$.descontoCupom").value(27.70));
    }

